<script>
document.querySelectorAll('.game-switch .game-tab').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.game-switch .game-tab').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.querySelector('#runnerMode').classList.toggle('hidden',btn.dataset.show!=='runnerMode');document.querySelector('#frogMode').classList.toggle('hidden',btn.dataset.show!=='frogMode');document.querySelector('#heroMode').classList.toggle('hidden',btn.dataset.show!=='heroMode')});
const cv=document.querySelector('#runner'),ctx=cv.getContext('2d'),coinEl=document.querySelector('#coins'),lifeEl=document.querySelector('#lives'),levelEl=document.querySelector('#level'),hint=document.querySelector('#missionHint');
let player={x:105,y:235,vy:0,on:true},obstacles=[],stars=[],particles=[],frame=0,coins=0,lives=3,level=1,paused=false,asking=false,runSpeed=5;
const qs=[{q:'Temanmu berbeda agama ingin ikut kerja kelompok. Sikap tepat adalah...',a:['Mengajak dan menghargainya','Menolaknya','Mengejeknya'],ok:0,good:'Hebat! Toleransi membuat kelompok makin kuat.'},{q:'Keputusan kelas terbaik diambil melalui...',a:['Musyawarah','Paksaan','Diam-diam'],ok:0,good:'Benar! Musyawarah adalah contoh demokrasi.'},{q:'Sikap bela negara yang dapat dilakukan siswa adalah...',a:['Menaati aturan dan belajar','Membuat keributan','Merusak fasilitas'],ok:0,good:'Tepat! Hal kecil yang baik adalah wujud bela negara.'}];
function jump(){if(!paused&&!asking&&player.on){player.vy=-13;player.on=false;burst(player.x,278,'#d7b27a',8)}}document.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();jump()}});document.querySelector('#jumpBtn').onclick=jump;document.querySelector('#pauseBtn').onclick=()=>{paused=!paused;document.querySelector('#pauseBtn').textContent=paused?'▶ Lanjut':'⏸ Jeda'};
function burst(x,y,color,count=12){for(let i=0;i<count;i++)particles.push({x,y,vx:(Math.random()-.5)*5,vy:(Math.random()-.7)*5,a:1,color})}function resetScene(){obstacles=[];stars=[];player.y=235;player.vy=0;player.on=true}
function showChallenge(){asking=true;paused=true;document.querySelector('#challenge').classList.remove('hidden');let q=qs[(level-1)%qs.length];document.querySelector('#challengeTitle').textContent='Level '+level+' - Tantangan!';document.querySelector('#challengeText').textContent=q.q;let box=document.querySelector('#challengeOptions');box.innerHTML='';q.a.forEach((a,i)=>{let b=document.createElement('button');b.textContent=a;b.onclick=()=>{if(i===q.ok){coins+=20;coinEl.textContent=coins;hint.textContent=q.good;level++;levelEl.textContent=level;document.querySelectorAll('.mission-line i').forEach((e,n)=>e.classList.toggle('active',n<level));}else{lives--;lifeEl.textContent=lives;hint.textContent='Coba lagi, nilai Pancasila selalu menuntun pilihan baik.'}document.querySelector('#challenge').classList.add('hidden');asking=false;paused=false;if(lives<=0){lives=3;coins=0;level=1;lifeEl.textContent=lives;coinEl.textContent=coins;levelEl.textContent=level;hint.textContent='Mulai lagi, petualang!'}resetScene()};box.appendChild(b)})}
function draw(){frame++;if(!paused){player.vy+=.7;player.y=Math.min(235,player.y+player.vy);if(player.y===235){player.vy=0;player.on=true}if(frame%Math.max(58,105-level*9)===0)obstacles.push({x:850,w:23,h:44});if(frame%75===0)stars.push({x:850,y:70+Math.random()*135});obstacles.forEach(o=>o.x-=runSpeed);stars.forEach(s=>s.x-=runSpeed*.82);particles.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.vy+=.15;p.a-=.03});obstacles=obstacles.filter(o=>o.x>-40);stars=stars.filter(s=>{if(Math.abs(s.x-player.x)<29&&Math.abs(s.y-(player.y+17))<33){coins+=5;coinEl.textContent=coins;burst(s.x,s.y,'#ffd34d');return false}return s.x>-30});particles=particles.filter(p=>p.a>0);if(obstacles.some(o=>o.x<player.x+35&&o.x+o.w>player.x&&player.y>205)){lives--;lifeEl.textContent=lives;burst(player.x,player.y,'#ff7365',20);resetScene();if(lives<=0){lives=3;coins=0;level=1;lifeEl.textContent=3;coinEl.textContent=0;levelEl.textContent=1;hint.textContent='Ayo mulai lagi!'}}if(coins>=level*35&&level<=3)showChallenge();if(level>3){hint.textContent='🏆 Desa Harmoni selesai! Kamu pejuang Pancasila.';paused=true}}
ctx.clearRect(0,0,840,330);let sky=ctx.createLinearGradient(0,0,0,330);sky.addColorStop(0,'#9ee5ff');sky.addColorStop(1,'#e7fbff');ctx.fillStyle=sky;ctx.fillRect(0,0,840,330);ctx.fillStyle='rgba(255,255,255,.85)';for(let i=0;i<4;i++){let cx=((i*245-frame*.25)%980)-80;ctx.beginPath();ctx.arc(cx,72,25,0,7);ctx.arc(cx+28,62,30,0,7);ctx.arc(cx+60,74,22,0,7);ctx.fill()}ctx.fillStyle='#86c278';for(let i=0;i<5;i++){let mx=((i*210-frame*.35)%1050)-100;ctx.beginPath();ctx.arc(mx,260,100,Math.PI,0);ctx.fill()}ctx.fillStyle='#4eab5c';ctx.fillRect(0,282,840,48);ctx.fillStyle='#2f8745';for(let i=0;i<840;i+=42)ctx.fillRect((i-frame*runSpeed)%840,295,27,6);particles.forEach(p=>{ctx.globalAlpha=p.a;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,4,0,7);ctx.fill();ctx.globalAlpha=1});ctx.fillStyle='#4b48b8';ctx.fillRect(player.x-18,player.y+12,35,30);ctx.fillStyle='#f3ad78';ctx.beginPath();ctx.arc(player.x,player.y,14,0,7);ctx.fill();ctx.fillStyle='#29306d';ctx.fillRect(player.x-13,player.y-10,27,7);let swing=Math.sin(frame*.42)*8;ctx.strokeStyle='#253957';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(player.x-8,player.y+41);ctx.lineTo(player.x-10+swing,player.y+51);ctx.moveTo(player.x+9,player.y+41);ctx.lineTo(player.x+11-swing,player.y+51);ctx.stroke();stars.forEach(s=>{ctx.font=(25+Math.sin(frame*.18)*3)+'px sans-serif';ctx.fillStyle='#ffd34d';ctx.fillText('★',s.x,s.y)});obstacles.forEach(o=>{ctx.fillStyle='#f15d63';ctx.fillRect(o.x,282-o.h,o.w,o.h);ctx.fillStyle='#fff';ctx.fillRect(o.x+5,247,5,5)});requestAnimationFrame(draw)}draw();
const frogQs=[{q:'Pancasila memiliki berapa sila?',a:['4','5','6'],ok:'5'},{q:'Semboyan bangsa Indonesia adalah...',a:['Bhinneka Tunggal Ika','Tut Wuri Handayani','Garuda Jaya'],ok:'Bhinneka Tunggal Ika'},{q:'Musyawarah mencerminkan sila ke...',a:['Kedua','Keempat','Kelima'],ok:'Keempat'}];let frogIndex=0,frogScore=0;function setFrog(){let q=frogQs[frogIndex%frogQs.length];document.querySelector('#frogQuestion').textContent=q.q;document.querySelectorAll('.answer-lily').forEach((b,i)=>{b.textContent=q.a[i];b.dataset.answer=q.a[i];b.disabled=false;b.classList.remove('correct','wrong')});document.querySelector('#frog').classList.remove('fall','hop');document.querySelector('#frogStatus').textContent='Klik batu jawaban yang benar.';document.querySelector('#nextFrog').classList.add('hidden')}document.querySelectorAll('.answer-lily').forEach(b=>b.onclick=()=>{let q=frogQs[frogIndex%frogQs.length],frog=document.querySelector('#frog');document.querySelectorAll('.answer-lily').forEach(x=>x.disabled=true);if(b.dataset.answer===q.ok){b.classList.add('correct');frog.classList.add('hop');frogScore+=10;document.querySelector('#frogScore').textContent=frogScore;document.querySelector('#frogStatus').textContent='✅ Lompatannya sukses! Jawabanmu benar.';document.querySelector('#nextFrog').classList.remove('hidden')}else{b.classList.add('wrong');frog.classList.add('fall');document.querySelector('#frogStatus').textContent='💦 Aduh, Kodok Panca jatuh ke air! Coba soal ini lagi.';setTimeout(setFrog,1300)}});document.querySelector('#nextFrog').onclick=()=>{frogIndex++;setFrog()};setFrog();
