];heroes.push({name:'Bung Tomo',wiki:'Bung_Tomo',clue:'Tokoh yang membangkitkan semangat perjuangan rakyat Surabaya pada 10 November.',img:'',a:[]});let heroIndex=0;function setHero(){let h=heroes[heroIndex%heroes.length],img=document.querySelector('#heroImage'),slug=(h.wiki||h.name).replaceAll(' ','_');img.src=h.img||'https://id.wikipedia.org/static/images/project-logos/idwiki.png';if(!h.img)fetch('https://id.wikipedia.org/api/rest_v1/page/summary/'+encodeURIComponent(slug)).then(r=>r.json()).then(data=>{if(data.thumbnail&&heroIndex%heroes.length===heroes.indexOf(h))img.src=data.thumbnail.source}).catch(()=>{});img.alt='Foto '+h.name;img.onerror=()=>{img.onerror=null;img.src='https://id.wikipedia.org/static/images/project-logos/idwiki.png'};document.querySelector('#heroClue').textContent=h.clue;document.querySelector('#heroQuestion').textContent='Siapakah tokoh pada gambar ini? ('+(heroIndex%heroes.length+1)+' / '+heroes.length+')';let opt=document.querySelector('#heroOptions'),answers=[h.name];while(answers.length<3){let candidate=heroes[Math.floor(Math.random()*heroes.length)].name;if(!answers.includes(candidate))answers.push(candidate)}opt.innerHTML='';answers.sort(()=>Math.random()-.5).forEach(a=>{let b=document.createElement('button');b.textContent=a;b.onclick=()=>{if(a===h.name){b.classList.add('correct');document.querySelector('#heroStatus').textContent='✅ Tepat! Ini adalah '+h.name+'.';document.querySelector('#nextHero').classList.remove('hidden');opt.querySelectorAll('button').forEach(x=>x.disabled=true)}else{b.classList.add('wrong');b.disabled=true;document.querySelector('#heroStatus').textContent='Belum tepat, lihat petunjuknya lagi ya.'}};opt.appendChild(b)});document.querySelector('#heroStatus').textContent='';document.querySelector('#nextHero').classList.add('hidden')}document.querySelector('#nextHero').onclick=()=>{heroIndex++;setHero()};setHero();
